# Shared colour atlas: every character/prop mesh maps its parts to swatches of one 16x16 grid,
# so a whole multi-coloured model is ONE mesh / ONE material (base_color + metal_rough + emissive).
G = 16; PX = 32; SIZE = G * PX
# name: (rgb 0..1, roughness, metallic, emissive rgb or None)
SW = {}
def sw(name, rgb, rough=0.6, metal=0.0, em=None): SW[name] = (len(SW), rgb, rough, metal, em)
sw('blue', (0.15, 0.45, 0.92), 0.55); sw('blue_d', (0.08, 0.22, 0.52), 0.6); sw('navy', (0.07, 0.09, 0.2), 0.7)
