sw('dkgrey', (0.22, 0.23, 0.25), 0.5, 0.4); sw('tan', (0.95, 0.8, 0.52), 0.8); sw('mutant', (0.92, 0.3, 0.22), 0.5); sw('mflash', (1, 0.9, 0.6), 0.3, 0, (1, 0.85, 0.5)); sw('rubber', (0.06, 0.06, 0.06), 0.8); sw('blue_g', (0.3, 0.5, 1.0), 0.3, 0, (0.25, 0.45, 1.0))
def uv(name):
    i = SW[name][0]; gx, gy = i % G, i // G
    return ((gx + 0.5) / G, (gy + 0.5) / G)
